assignments.value:
={{
(() => {
  const raw = $json['Budget '];

  if (raw === undefined || raw === null || String(raw).trim() === "") {
    return "Needs Review";
  }

  const value = String(raw)
    .trim()
    .replace(/,/g, "")
    .replace(/^\s*(USD|\$)\s*/i, "")
    .replace(/\s*(USD|\$)\s*$/i, "")
    .trim();

  const match = value.match(/^(\d+(?:\.\d+)?)\s*(k)?$/i);

  if (!match) return "Needs Review";

  const budget = Number(match[1]) * (match[2] ? 1000 : 1);

  if (!Number.isFinite(budget) || budget < 0) {
    return "Needs Review";
  }

  if (budget < 1000) return "Normal";
  if (budget <= 3000) return "Good";

  return "Great (Hot Lead)";
})()
}}

